<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {useRoute} from 'vue-router'
import type {components} from '@adc/contracts'
import {createProtectedClient} from '../../api/protected'
import {ApiFailure,prepareCommand,UnknownOutcomeError,type PreparedCommand} from '../../api/http'
import {shanghaiToday,shiftDate} from '../schedules/week'
import AppointmentReviewQueue from '../../components/AppointmentReviewQueue.vue'
type Appointment=components['schemas']['AppointmentView'];type Candidate=components['schemas']['Candidate'];type Catalog=components['schemas']['CatalogItem']
const api=createProtectedClient(),route=useRoute(),id=ref(typeof route.query.appointmentId==='string'?route.query.appointmentId:''),source=ref<Appointment|null>(null),queueRevision=ref(0),patient=ref<components['schemas']['PatientView']|null>(null),verification=ref(''),number=ref(''),birth=ref(''),service=ref(''),person=ref(false),intent=ref(false),reason=ref(''),action=ref<'RESCHEDULE'|'CLINIC_CANCEL'>('RESCHEDULE'),clinics=ref<Catalog[]>([]),treatments=ref<Catalog[]>([]),clinic=ref(''),date=ref(shanghaiToday()),treatmentIds=ref<string[]>([]),slots=ref<Candidate[]>([]),slot=ref<Candidate|null>(null),next=ref<string|null>(null),result=ref<components['schemas']['RescheduleView']|null>(null),busy=ref(false),unknown=ref(false),error=ref(''),notice=ref('')
let pending:PreparedCommand|undefined
const time=(at:string)=>new Date(at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})
async function failed(failure:unknown){error.value=failure instanceof ApiFailure?({SOURCE_NOT_SUSPENDED:'原班次未停诊，不能按停诊改约处理。',SLOT_OCCUPIED:'目标时隙已被占用，旧预约仍待处理，请重新选择。',ALLERGY_CONFIRMATION_REQUIRED:'当前过敏资料需先核实，旧预约仍保留待处理。',APPOINTMENT_ALREADY_HANDLED:'原预约已处理，请重新读取当前事实。'}[failure.code]??`未完成：${failure.message}`):'服务暂不可用。';if(failure instanceof ApiFailure && [401,403].includes(failure.status)){source.value=null;patient.value=null;verification.value='';result.value=null;slots.value=[]}if(failure instanceof ApiFailure && failure.code==='APPOINTMENT_ALREADY_HANDLED')try{source.value=await api.get(`/api/v1/appointments/${encodeURIComponent(id.value)}`)}catch{source.value=null}}
function resetProof(){patient.value=null;verification.value='';intent.value=false}
function applySource(row:Appointment){id.value=row.appointment_id;source.value=row;clinic.value=row.clinic_id;resetProof();result.value=null;notice.value='';error.value='';slot.value=null;slots.value=[]}
function selectSource(row:Appointment){if(!pending && !busy.value)applySource(row)}
async function read(){busy.value=true;error.value='';try{applySource(await api.get<Appointment>(`/api/v1/appointments/${encodeURIComponent(id.value)}`))}catch(failure){await failed(failure)}finally{busy.value=false}}
async function execute(){if(!pending)return;busy.value=true;error.value='';const operation=pending.operation;try{const response=await api.execute<components['schemas']['PatientLookupResult']|components['schemas']['RescheduleView']>(pending);if(operation==='lookupPatient'){const proof=response.data as components['schemas']['PatientLookupResult'];if(!source.value || proof.patient.patient_id!==source.value.patient_id)throw new ApiFailure(422,'PATIENT_VERIFICATION_MISMATCH');patient.value=proof.patient;verification.value=proof.verification_reference;notice.value='原约患者及实际服务依据已核验。'}else{result.value=response.data as components['schemas']['RescheduleView'];source.value=result.value.old_appointment;notice.value=result.value.new_appointment?'改约已完成，新旧预约及来源链已保存。':'已核实登记诊所取消，历史保留。';queueRevision.value++;slot.value=null;slots.value=[]}pending=undefined;unknown.value=false}catch(failure){if(failure instanceof UnknownOutcomeError){unknown.value=true;error.value='结果确认中，请保留当前页面并重新确认办理结果。'}else{pending=undefined;unknown.value=false;await failed(failure)}}finally{busy.value=false}}
async function lookup(){if(pending || !source.value)return;pending=prepareCommand('lookupPatient','POST','/api/v1/patients/lookup',{patient_number:number.value,date_of_birth:birth.value,verification_basis:{clinic_id:source.value.clinic_id,person_confirmed:person.value,service_basis:service.value}});await execute()}
async function search(more=false){if(pending)return;busy.value=true;error.value='';slot.value=null;try{const query=new URLSearchParams({clinic_id:clinic.value,start:`${date.value}T00:00:00+08:00`,end:`${shiftDate(date.value,1)}T00:00:00+08:00`,limit:'100'});for(const treatment of treatmentIds.value)query.append('treatment_ids',treatment);if(more && next.value)query.set('cursor',next.value);const page=await api.get<{items:Candidate[];next_cursor:string|null}>(`/api/v1/appointment-candidates?${query}`);slots.value=more?[...slots.value,...page.items]:page.items;next.value=page.next_cursor;if(!slots.value.length)notice.value='暂无合适新位，原预约仍待处理。'}catch(failure){await failed(failure)}finally{busy.value=false}}
async function save(){if(pending || !intent.value || !source.value)return;const body={action:action.value,reason:reason.value,verification_reference:verification.value,...(action.value==='RESCHEDULE' && slot.value?{new_clinic_id:slot.value.clinic_id,new_schedule_id:slot.value.schedule_id,new_scheduled_at:slot.value.starts_at}:{})};pending=prepareCommand('rescheduleAppointment','POST',`/api/v1/appointments/${source.value.appointment_id}/reschedule`,body);await execute()}
async function query(){if(!pending)return;try{const receipt=await api.requestResult<{status:string}>(pending);notice.value=receipt.status==='SUCCEEDED'?'原请求已成功，请重新确认读取授权结果。':'尚未确认成功，请保留当前页面。'}catch(failure){await failed(failure)}}
function wait(){if(pending)return;slot.value=null;notice.value='原预约仍保留待处理，尚未取消或创建新预约。'}
async function catalog(path:string){const items:Catalog[]=[];let cursor:string|null=null;do{const page:{items:Catalog[];next_cursor:string|null}=await api.get(`${path}?limit=100${cursor?`&cursor=${encodeURIComponent(cursor)}`:''}`);items.push(...page.items);cursor=page.next_cursor}while(cursor);return items}
onMounted(async()=>{try{[clinics.value,treatments.value]=await Promise.all([catalog('/api/v1/clinics'),catalog('/api/v1/treatments')]);if(id.value)await read()}catch(failure){await failed(failure)}})
</script>
<template><section><h1>停诊改约与诊所取消</h1><p>原预约保留历史。无合适新位可继续待处理，不能计为患者取消或爽约。</p><p v-if="error" role="alert" class="error-message">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><div v-if="unknown"><button :disabled="busy" @click="query">查询办理进度</button><button :disabled="busy" @click="execute">重新确认办理结果</button></div><AppointmentReviewQueue v-if="!unknown" :key="queueRevision" kind="reschedule" @select="selectSource" />
<fieldset :disabled="busy || unknown"><legend>原预约</legend><label>原预约 ID<input v-model="id" @input="source=null;resetProof()"></label><button @click="read">重新读取原预约</button></fieldset><p v-if="source">原预约 {{source.appointment_id}} · {{time(source.scheduled_at)}}（北京时间） · {{source.status==='SCHEDULED'?'待处理':source.status==='CANCELLED'?'已取消':'已经进入后续就诊状态'}}</p>
<form v-if="source" @submit.prevent="lookup"><fieldset :disabled="busy || unknown"><legend>核实原约患者与实际服务</legend><label>原患者编号<input v-model="number" required @input="resetProof"></label><label>出生日期<input v-model="birth" type="date" required @change="resetProof"></label><label>本次服务依据<input v-model="service" required maxlength="255" @input="resetProof"></label><label><input v-model="person" type="checkbox" required @change="resetProof">已人工核实原约患者本人</label><button>核验原约患者</button></fieldset></form><p v-if="patient">已核实：{{patient.full_name}} · {{patient.patient_number}}。{{patient.allergy_confirmation_reference?'当前过敏核验已有依据。':'当前过敏资料尚需到患者资料页面核实。'}}</p>
<fieldset v-if="source" :disabled="busy || unknown || source.status!=='SCHEDULED'"><legend>核实患者处理意向</legend><label>处理方式<select v-model="action"><option value="RESCHEDULE">选择正常班次改约</option><option value="CLINIC_CANCEL">患者确认不再安排，登记诊所取消</option></select></label><template v-if="action==='RESCHEDULE'"><label>目标诊所<select v-model="clinic" @change="slots=[];slot=null"><option v-for="c in clinics" :key="c.id" :value="c.id">{{c.label}}</option></select></label><label>目标日期<input v-model="date" type="date" @change="slots=[];slot=null"></label><label>原预约期望治疗项目<select v-model="treatmentIds" multiple @change="slots=[];slot=null"><option v-for="t in treatments" :key="t.id" :value="t.id">{{t.label}}</option></select></label><p>按原约及患者确认的项目筛选；保存时沿用并复核原预约全部期望项目，不在此变更项目。</p><button :disabled="!treatmentIds.length || !clinic" @click="search()">查询改约候选</button><div class="candidates"><button v-for="candidate in slots" :key="candidate.schedule_id+candidate.starts_at" :aria-pressed="slot===candidate" @click="slot=candidate">{{time(candidate.starts_at)}} · {{candidate.dentist_name}}</button></div><button v-if="next" @click="search(true)">更多候选</button></template><label>处理原因与患者意向<input v-model="reason" maxlength="255" required></label><label><input v-model="intent" type="checkbox">已与患者核实本次处理方式及安排</label><button :disabled="!intent || !verification || !reason || (action==='RESCHEDULE' && !slot)" @click="save">确认本次停诊处理</button><button @click="wait">暂不办理，保留待处理</button></fieldset>
<section v-if="result" class="source-chain"><h2>处理结果与来源链</h2><p>旧预约 {{result.old_appointment.appointment_id}} · {{result.old_appointment.cancellation_kind==='CLINIC_RESCHEDULE'?'诊所改约取消':'诊所取消'}}</p><p v-if="result.new_appointment">新预约 {{result.new_appointment.appointment_id}} · 待就诊 · 来源 {{result.new_appointment.rescheduled_from_id}}</p><p v-else>未创建新预约。</p></section><RouterLink to="/appointment-booking">返回预约管理</RouterLink></section></template>
<style scoped>fieldset{display:flex;gap:16px;align-items:end;flex-wrap:wrap;margin:20px 0;padding:18px}label{display:grid;gap:7px}input,select{padding:8px;border:1px solid #bacdc5;border-radius:5px}button{padding:10px 14px}.candidates{display:flex;gap:10px;flex-wrap:wrap}.candidates [aria-pressed=true]{background:#22664e;color:white}.source-chain{padding:18px;background:#edf5f1}</style>

